import java.util.*;
import java.util.concurrent.*;

// Represents one rendition to be produced for a title, e.g. "1080p" in codec "av1".
class RenditionSpec {
    final String resolution;
    final String codec;
    RenditionSpec(String resolution, String codec) {
        this.resolution = resolution;
        this.codec = codec;
    }
    String key() { return resolution + ":" + codec; }
}

// One unit of encode work: a single rendition of a single title.
class TranscodeJob {
    final String jobId;
    final String titleId;
    final RenditionSpec rendition;
    int attempts = 0;
    TranscodeJob(String jobId, String titleId, RenditionSpec rendition) {
        this.jobId = jobId;
        this.titleId = titleId;
        this.rendition = rendition;
    }
}

// Dispatches one job per rendition in the ladder, tracks per-title completion,
// and retries failed jobs with a bounded attempt count before dead-lettering them.
class TranscodingJobDispatcher {
    private static final int MAX_ATTEMPTS = 3;
    private final BlockingQueue<TranscodeJob> jobQueue = new LinkedBlockingQueue<>();
    private final List<TranscodeJob> deadLetterQueue = new ArrayList<>();
    // Tracks how many renditions are still outstanding for each title.
    private final Map<String, Integer> outstandingByTitle = new ConcurrentHashMap<>();

