    // rendition in the ladder rather than one big job for the whole title, so
    // renditions encode in parallel instead of one after another.
    void submitTitle(String titleId, List<RenditionSpec> ladder) {
        outstandingByTitle.put(titleId, ladder.size());
        for (RenditionSpec r : ladder) {
            String jobId = titleId + ":" + r.key();
            jobQueue.offer(new TranscodeJob(jobId, titleId, r));
        }
    }

    // A worker calls this to pick up the next available unit of work.
    TranscodeJob pollNextJob() throws InterruptedException {
        return jobQueue.take();
    }

    // A worker reports success after writing the encoded rendition to origin storage.
    void reportSuccess(TranscodeJob job) {
        outstandingByTitle.computeIfPresent(job.titleId, (id, remaining) -> remaining - 1);
        if (outstandingByTitle.get(job.titleId) == 0) {
            onTitleFullyEncoded(job.titleId);
        }
    }

    // A worker reports failure. The job is retried up to MAX_ATTEMPTS times,
    // after which it is dead-lettered for a human to review.
    void reportFailure(TranscodeJob job) {
        job.attempts++;
        if (job.attempts < MAX_ATTEMPTS) {
            jobQueue.offer(job); // simple retry, a real system would add a backoff delay here
        } else {
            deadLetterQueue.add(job);
        }
    }

    // Hook for whatever should happen once every rendition for a title has landed,
    // such as triggering CDN prewarm.
    private void onTitleFullyEncoded(String titleId) {
        System.out.println("Title fully encoded and ready to prewarm: " + titleId);
    }

