struct TranscodeJob {
    std::string jobId;
    std::string titleId;
    RenditionSpec rendition;
    int attempts = 0;
};

// Dispatches one job per rendition, tracks per-title completion, and retries
// failed jobs with a bounded attempt count before dead-lettering them.
class TranscodingJobDispatcher {
public:
    static const int MAX_ATTEMPTS = 3;

    void submitTitle(const std::string& titleId, const std::vector<RenditionSpec>& ladder) {
        std::lock_guard<std::mutex> lock(mutex_);
        outstandingByTitle_[titleId] = static_cast<int>(ladder.size());
        for (const auto& r : ladder) {
            TranscodeJob job{titleId + ":" + r.key(), titleId, r, 0};
            jobQueue_.push(job);
        }
    }

    // Non-blocking pop for this illustrative version; a real system would use a
    // condition variable to wait for new work instead of returning false.
    bool pollNextJob(TranscodeJob& out) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (jobQueue_.empty()) return false;
        out = jobQueue_.front();
        jobQueue_.pop();
        return true;
    }

    void reportSuccess(const TranscodeJob& job) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (--outstandingByTitle_[job.titleId] == 0) {
            onTitleFullyEncoded(job.titleId);
        }
    }

    void reportFailure(TranscodeJob job) {
        std::lock_guard<std::mutex> lock(mutex_);
        job.attempts++;
        if (job.attempts < MAX_ATTEMPTS) {
            jobQueue_.push(job); // simple retry, a real system adds a backoff delay
        } else {
            deadLetterQueue_.push_back(job);
        }
    }

    const std::vector<TranscodeJob>& getDeadLetterQueue() const { return deadLetterQueue_; }

private:
    std::queue<TranscodeJob> jobQueue_;
    std::vector<TranscodeJob> deadLetterQueue_;
    std::unordered_map<std::string, int> outstandingByTitle_;
    std::mutex mutex_;

    void onTitleFullyEncoded(const std::string& titleId) {
        std::cout << "Title fully encoded and ready to prewarm: " << titleId << std::endl;
