import java.util.*;

// One quality variant of one segment: which rendition, its bitrate, and its URL.
class SegmentVariant {
    final String resolution;
    final int bitrateKbps;
    final String url;
    SegmentVariant(String resolution, int bitrateKbps, String url) {
        this.resolution = resolution;
        this.bitrateKbps = bitrateKbps;
        this.url = url;
    }
}

// A single few-second chunk of video, available in every quality on the ladder.
class Segment {
    final int index;
    final List<SegmentVariant> variants = new ArrayList<>();
    Segment(int index) { this.index = index; }
}

// Builds the manifest a player reads: for every segment, every available quality.
// This is the concrete data structure behind an HLS or DASH manifest file.
class AdaptiveBitrateManifestBuilder {
    private final Map<Integer, Segment> segments = new LinkedHashMap<>();

    // Registers one encoded variant for one segment. Called once per rendition,
    // per segment, while the packaging step is writing the manifest out.
    void addVariant(int segmentIndex, String resolution, int bitrateKbps, String url) {
        Segment seg = segments.computeIfAbsent(segmentIndex, Segment::new);
        seg.variants.add(new SegmentVariant(resolution, bitrateKbps, url));
    }

    // Returns every quality available for a segment, sorted ascending by bitrate
    // so a player can walk the ladder up or down cleanly.
    List<SegmentVariant> variantsForSegment(int segmentIndex) {
        Segment seg = segments.get(segmentIndex);
        if (seg == null) return Collections.emptyList();
        List<SegmentVariant> sorted = new ArrayList<>(seg.variants);
        sorted.sort(Comparator.comparingInt(v -> v.bitrateKbps));
        return sorted;
    }

    int segmentCount() { return segments.size(); }
}

// Decides which quality to request for the next segment, given recently measured
// throughput and how much video is currently sitting in the client's buffer.
// This is the logic that lets Alice's player step down smoothly in a subway
// tunnel and step back up once signal recovers, without ever stalling playback.
class AbrQualitySelector {
    // Only step up in quality if the buffer is comfortably healthy, so a lucky
    // fast segment is not immediately followed by a stall.
    private static final double SAFE_BUFFER_SECONDS = 12.0;
    // Never request a quality whose bitrate is close to the full measured
    // throughput. This margin absorbs normal network jitter.
    private static final double SAFETY_MARGIN = 0.8;

    // variants must already be sorted ascending by bitrate, as returned by
    // AdaptiveBitrateManifestBuilder.variantsForSegment.
    SegmentVariant selectNext(List<SegmentVariant> variants, double measuredThroughputKbps, double bufferedSeconds) {
        double sustainableBitrate = measuredThroughputKbps * SAFETY_MARGIN;
        SegmentVariant choice = variants.get(0); // start from the lowest quality as a safe floor

        for (SegmentVariant v : variants) {
            boolean throughputSupportsIt = v.bitrateKbps <= sustainableBitrate;
            // Only allow stepping up to a demanding rendition if the buffer also
            // has headroom, so a brief throughput spike does not overcommit.
            boolean bufferSupportsIt = bufferedSeconds >= SAFE_BUFFER_SECONDS || v.bitrateKbps <= choice.bitrateKbps;
            if (throughputSupportsIt && bufferSupportsIt) {
                choice = v; // keep walking up the ladder while both conditions hold
            } else {
                break; // variants are sorted ascending, so nothing further will fit either
            }
        }
        return choice;
    }
}

