import java.util.concurrent.*;

// One stored watch position for a profile and title, with the timestamp it was written at.
class WatchPositionRecord {
    final int positionSeconds;
    final Instant updatedAt;
    WatchPositionRecord(int positionSeconds, Instant updatedAt) {
        this.positionSeconds = positionSeconds;
        this.updatedAt = updatedAt;
    }
}

// Keeps the latest watch position per (profileId, titleId), resolving concurrent
// updates from multiple devices with a simple last-write-wins rule by timestamp.
class WatchPositionSyncService {
    // Keyed by "profileId:titleId" to keep the lookup a single hash operation,
    // matching the composite shard key used by the real datastore.
    private final ConcurrentHashMap<String, WatchPositionRecord> store = new ConcurrentHashMap<>();

    private String key(String profileId, String titleId) {
        return profileId + ":" + titleId;
    }

    // Applies an incoming heartbeat. If a newer record already exists, per its
    // own timestamp, this update is silently discarded rather than applied,
    // which is what protects against a delayed heartbeat rewinding progress.
    void heartbeat(String profileId, String titleId, int positionSeconds, Instant clientTimestamp) {
        String k = key(profileId, titleId);
        store.merge(k, new WatchPositionRecord(positionSeconds, clientTimestamp),
            (existing, incoming) -> incoming.updatedAt.isAfter(existing.updatedAt) ? incoming : existing);
    }

    // Reads the current resume position for a title, used when a new device
    // opens something already in progress elsewhere.
    Optional<Integer> resumePosition(String profileId, String titleId) {
        WatchPositionRecord r = store.get(key(profileId, titleId));
        return r == null ? Optional.empty() : Optional.of(r.positionSeconds);
    }
}

