        self.store = {}  # "profileId:titleId" -> WatchPositionRecord

    def _key(self, profile_id, title_id):
        return f"{profile_id}:{title_id}"

    def heartbeat(self, profile_id, title_id, position_seconds, client_timestamp):
        k = self._key(profile_id, title_id)
        existing = self.store.get(k)
        # Discard the update if a newer record already exists, which is what
        # protects against a delayed heartbeat rewinding progress.
        if existing is None or client_timestamp > existing.updated_at:
            self.store[k] = WatchPositionRecord(position_seconds, client_timestamp)

    def resume_position(self, profile_id, title_id) -> Optional[int]:
        record = self.store.get(self._key(profile_id, title_id))
        return record.position_seconds if record else None

