import java.util.*;
import java.util.function.*;

// A small illustrative stand-in for an ISP edge cache appliance: a bounded
// LRU-style cache of segment bytes that falls back to a slower upstream, the
// regional tier or origin, on a miss, then populates itself for next time.
class CdnEdgeCacheClient {
    private final int capacity;
    // LinkedHashMap in access order gives a cheap LRU eviction policy for free.
    private final LinkedHashMap<String, byte[]> cache;
    // Represents the next tier up: regional cache first, origin storage beyond that.
    private final Function<String, byte[]> upstreamFetch;

    CdnEdgeCacheClient(int capacity, Function<String, byte[]> upstreamFetch) {
        this.capacity = capacity;
        this.upstreamFetch = upstreamFetch;
        this.cache = new LinkedHashMap<String, byte[]>(16, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, byte[]> eldest) {
                return size() > CdnEdgeCacheClient.this.capacity; // evict least recently used once full
            }
        };
    }

    // Fetches a segment, serving from the local cache when possible and only
    // reaching upstream on a miss.
    byte[] fetchSegment(String segmentKey) {
        byte[] cached = cache.get(segmentKey);
        if (cached != null) {
            return cached; // cache hit, no upstream trip at all
        }
        byte[] fetched = upstreamFetch.apply(segmentKey); // cache miss, pull from regional or origin
        cache.put(segmentKey, fetched); // populate so the next request for this segment is a hit
        return fetched;
    }
}

