#include <vector>
#include <functional>

// A small illustrative stand-in for an ISP edge cache appliance: a bounded
// LRU cache of segment bytes that falls back to a slower upstream on a miss.
class CdnEdgeCacheClient {
public:
    using Bytes = std::vector<char>;
    using UpstreamFetch = std::function<Bytes(const std::string&)>;

    CdnEdgeCacheClient(size_t capacity, UpstreamFetch upstreamFetch)
        : capacity_(capacity), upstreamFetch_(std::move(upstreamFetch)) {}

    Bytes fetchSegment(const std::string& segmentKey) {
        auto it = index_.find(segmentKey);
        if (it != index_.end()) {
            // Move to the front of the list to mark it most recently used.
            lru_.splice(lru_.begin(), lru_, it->second);
            return it->second->second; // cache hit, no upstream trip
        }

        Bytes fetched = upstreamFetch_(segmentKey); // cache miss, pull from regional or origin
        lru_.emplace_front(segmentKey, fetched);
        index_[segmentKey] = lru_.begin();
        if (lru_.size() > capacity_) {
            index_.erase(lru_.back().first); // evict least recently used
            lru_.pop_back();
        }
        return fetched;
    }

private:
    size_t capacity_;
    UpstreamFetch upstreamFetch_;
    std::list<std::pair<std::string, Bytes>> lru_;
    std::unordered_map<std::string, std::list<std::pair<std::string, Bytes>>::iterator> index_;
};

